func sendIndicatorLabel(v view, state engineapi.MessageSendState) string {
	if state == "submitted" {
		return v.Text.SendAccepted
	}
	if state == "unknown" {
		return v.Text.SendUnconfirmed
	}
	return v.stateLabel(state)
}

func messageSide(own bool) chatbubble.Side {
	if own {
		return chatbubble.Sent
	}
	return chatbubble.Received
}

func selectedAccountID(v view) string {
	if v.Selected != nil {
		return v.Selected.AccountId
	}
	return ""
}

